protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: throws in EF Core 9 Cosmos provider.
    // Manage indexing via the container's indexing policy in Azure Portal/Bicep.
    modelBuilder.Entity<Product>().ToContainer("Products");

    // Preserve EF Core 8 discriminator property name ("Discriminator" → not "$type")
    // so existing documents and direct SQL queries (c.Discriminator) keep working.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // Preserve EF Core 8 compound id format ("Product|123") so existing 500K
    // documents remain addressable by FindAsync and point-reads.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

